"use client";

import { useEffect, useState, useCallback } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import {
  addToComparison,
  clearComparison,
  getComparisonItems,
  isInComparison,
  removeFromComparison,
  type ComparisonItem,
} from "./comparison-storage";
import { cop } from "@/features/orders/types";

export interface ComparisonProduct {
  id: number;
  name: string;
  slug: string;
  category: { id: number; name: string; slug: string };
  brand: { id: number; name: string; slug: string };
  image_url: string | null;
  description: string;
  warranty: string;
  min_price: string;
  max_price: string;
  promotional_min_price: string | null;
  has_promotion: boolean;
  total_stock: number;
  is_available: boolean;
  attributes: Record<string, { name: string; value: string }>;
}

export interface ComparisonResponse {
  category: { id: number; name: string; slug: string };
  attributes: { code: string; name: string }[];
  products: ComparisonProduct[];
}

/**
 * Button to toggle a product into/out of comparison list.
 */
export function CompareButton({
  item,
  className = "",
}: {
  item: ComparisonItem;
  className?: string;
}) {
  const [selected, setSelected] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const check = useCallback(() => {
    setSelected(isInComparison(item.id));
  }, [item.id]);

  useEffect(() => {
    check();
    window.addEventListener("comparison-updated", check);
    return () => window.removeEventListener("comparison-updated", check);
  }, [check]);

  const handleToggle = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (selected) {
      removeFromComparison(item.id);
      setSelected(false);
    } else {
      const res = addToComparison(item);
      if (!res.success) {
        setFeedback(res.error || "No se pudo agregar");
        setTimeout(() => setFeedback(null), 3500);
      } else {
        setSelected(true);
      }
    }
  };

  return (
    <div className="relative inline-block">
      <button
        type="button"
        onClick={handleToggle}
        aria-pressed={selected}
        title={selected ? "Quitar de la comparación" : "Agregar a la comparación (máx 4 de la misma categoría)"}
        className={`inline-flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded transition font-medium border ${
          selected
            ? "bg-blue-600 text-white border-blue-600 hover:bg-blue-700"
            : "bg-white text-gray-700 border-gray-300 hover:bg-gray-50 hover:text-blue-600"
        } ${className}`}
      >
        <span>{selected ? "✓" : "⚖️"}</span>
        <span>{selected ? "En comparación" : "Comparar"}</span>
      </button>

      {feedback && (
        <div
          role="alert"
          className="absolute bottom-full mb-1 left-0 z-50 whitespace-nowrap bg-red-600 text-white text-xs px-2.5 py-1 rounded shadow-lg"
        >
          {feedback}
        </div>
      )}
    </div>
  );
}

/**
 * Floating bar showing selected products and quick link to /comparar.
 */
export function ComparisonFloatingBar() {
  const router = useRouter();
  const [items, setItems] = useState<ComparisonItem[]>([]);

  const refresh = useCallback(() => {
    setItems(getComparisonItems());
  }, []);

  useEffect(() => {
    refresh();
    window.addEventListener("comparison-updated", refresh);
    return () => window.removeEventListener("comparison-updated", refresh);
  }, [refresh]);

  if (items.length === 0) return null;

  const canCompare = items.length >= 2;

  const handleGoCompare = () => {
    const ids = items.map((i) => i.id).join(",");
    router.push(`/comparar?ids=${ids}`);
  };

  return (
    <aside
      aria-label="Barra de comparación de productos"
      className="fixed bottom-4 left-1/2 -translate-x-1/2 z-40 bg-gray-900/95 text-white backdrop-blur px-4 py-3 rounded-xl shadow-2xl flex flex-wrap items-center gap-4 max-w-2xl w-[94vw] border border-gray-700"
    >
      <div className="flex items-center gap-2 text-xs">
        <span className="font-semibold text-sm">⚖️ Comparar ({items.length}/4)</span>
        <span className="text-gray-400 hidden sm:inline">
          {items[0]?.category_name ? `(${items[0].category_name})` : ""}
        </span>
      </div>

      <div className="flex items-center gap-2 overflow-x-auto flex-1 py-1">
        {items.map((item) => (
          <div
            key={item.id}
            className="flex items-center gap-1.5 bg-gray-800 border border-gray-700 rounded-lg px-2 py-1 text-xs shrink-0"
          >
            {item.image_url ? (
              <Image
                src={item.image_url}
                alt={item.name}
                width={20}
                height={20}
                unoptimized
                className="w-5 h-5 rounded object-cover"
              />
            ) : (
              <span className="w-5 h-5 bg-gray-700 rounded flex items-center justify-center text-[10px]">📦</span>
            )}
            <span className="max-w-[100px] truncate">{item.name}</span>
            <button
              type="button"
              onClick={() => removeFromComparison(item.id)}
              className="text-gray-400 hover:text-red-400 ml-1 font-bold"
              aria-label={`Quitar ${item.name}`}
            >
              ✕
            </button>
          </div>
        ))}
      </div>

      <div className="flex items-center gap-2 text-xs shrink-0">
        <button
          type="button"
          onClick={handleGoCompare}
          disabled={!canCompare}
          className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-medium px-3.5 py-1.5 rounded transition"
        >
          {canCompare ? `Comparar (${items.length})` : "Elige al menos 2"}
        </button>
        <button
          type="button"
          onClick={() => clearComparison()}
          className="text-gray-400 hover:text-white underline text-xs"
        >
          Limpiar
        </button>
      </div>
    </aside>
  );
}

/**
 * Full page comparison matrix component for /comparar.
 */
export function ProductComparisonView() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const idsParam = searchParams?.get("ids") ?? "";
  const slugsParam = searchParams?.get("slugs") ?? "";

  const [data, setData] = useState<ComparisonResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchComparison = useCallback(async () => {
    setLoading(true);
    setError(null);

    let query = idsParam ? `ids=${encodeURIComponent(idsParam)}` : "";
    if (!query && slugsParam) {
      query = `slugs=${encodeURIComponent(slugsParam)}`;
    }

    // Fallback to storage if no query in URL
    if (!query) {
      const stored = getComparisonItems();
      if (stored.length >= 2) {
        query = `ids=${stored.map((i) => i.id).join(",")}`;
      } else {
        setLoading(false);
        setError("Debes seleccionar al menos 2 productos para comparar.");
        return;
      }
    }

    try {
      const res = await fetch(`/api/v1/products/compare/?${query}`);
      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.detail || "Error al comparar productos.");
      }
      setData(json);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Error inesperado");
    } finally {
      setLoading(false);
    }
  }, [idsParam, slugsParam]);

  useEffect(() => {
    fetchComparison();
  }, [fetchComparison]);

  const handleRemoveProduct = (productId: number) => {
    removeFromComparison(productId);
    if (!data) return;
    const remaining = data.products.filter((p) => p.id !== productId);
    if (remaining.length < 2) {
      setData(null);
      setError("Debes seleccionar al menos 2 productos para comparar.");
      router.push("/catalogo");
    } else {
      setData({
        ...data,
        products: remaining,
      });
      router.replace(`/comparar?ids=${remaining.map((p) => p.id).join(",")}`);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-4 sm:p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 border-b pb-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-gray-900">
            Comparador de Productos
          </h1>
          <p className="text-sm text-gray-500">
            {data?.category
              ? `Comparando ${data.products.length} productos en la categoría ${data.category.name}`
              : "Compara especificaciones técnicas, precio y disponibilidad"}
          </p>
        </div>

        <div className="flex gap-2">
          <Link
            href="/catalogo"
            className="text-xs bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-2 rounded font-medium transition"
          >
            ← Volver al catálogo
          </Link>
          {data && (
            <button
              onClick={() => {
                clearComparison();
                router.push("/catalogo");
              }}
              className="text-xs text-red-600 hover:text-red-700 px-3 py-2 rounded font-medium"
            >
              Limpiar comparación
            </button>
          )}
        </div>
      </div>

      {loading && (
        <div className="p-12 text-center text-gray-500" role="status">
          Cargando matriz comparativa...
        </div>
      )}

      {error && !loading && (
        <div role="alert" className="p-6 bg-amber-50 border border-amber-200 rounded-lg text-amber-900 text-sm space-y-3">
          <p className="font-semibold">{error}</p>
          <p className="text-xs text-amber-800">
            Puedes explorar el catálogo y marcar hasta 4 productos de la misma categoría haciendo clic en el botón <strong>Comparar</strong>.
          </p>
          <Link
            href="/catalogo"
            className="inline-block bg-blue-600 hover:bg-blue-700 text-white text-xs px-4 py-2 rounded font-medium transition"
          >
            Explorar catálogo
          </Link>
        </div>
      )}

      {/* Comparison Matrix Table */}
      {data && data.products.length >= 2 && !loading && (
        <div className="overflow-x-auto bg-white border rounded-xl shadow-sm">
          <table className="w-full border-collapse text-sm text-left">
            <thead>
              <tr className="bg-gray-50 border-b">
                <th scope="col" className="p-4 w-48 min-w-[180px] font-semibold text-gray-600 uppercase text-xs tracking-wider">
                  Característica
                </th>
                {data.products.map((p) => (
                  <th key={p.id} scope="col" className="p-4 min-w-[240px] max-w-[300px] align-top border-l">
                    <div className="space-y-3 text-center">
                      <div className="flex justify-end">
                        <button
                          type="button"
                          onClick={() => handleRemoveProduct(p.id)}
                          className="text-gray-400 hover:text-red-500 text-xs font-bold"
                          title="Quitar de la comparación"
                          aria-label={`Quitar ${p.name}`}
                        >
                          ✕ Quitar
                        </button>
                      </div>

                      <div className="w-36 h-36 mx-auto bg-gray-50 rounded-lg flex items-center justify-center overflow-hidden border">
                        {p.image_url ? (
                          <Image
                            src={p.image_url}
                            alt={p.name}
                            width={140}
                            height={140}
                            unoptimized
                            className="object-contain w-full h-full"
                          />
                        ) : (
                          <span className="text-3xl text-gray-300">📦</span>
                        )}
                      </div>

                      <div>
                        <p className="text-xs text-blue-600 font-semibold">{p.brand.name}</p>
                        <h2 className="font-bold text-gray-900 text-sm leading-tight hover:text-blue-600">
                          <Link href={`/catalogo/${p.slug}`}>{p.name}</Link>
                        </h2>
                      </div>

                      {/* Price */}
                      <div>
                        {p.has_promotion && p.promotional_min_price ? (
                          <div className="space-y-0.5">
                            <span className="text-xs bg-red-100 text-red-700 font-bold px-2 py-0.5 rounded">¡Oferta!</span>
                            <p className="text-lg font-extrabold text-red-600">
                              {cop(p.promotional_min_price)}
                            </p>
                            <p className="text-xs text-gray-400 line-through">
                              {cop(p.min_price)}
                            </p>
                          </div>
                        ) : (
                          <p className="text-lg font-bold text-gray-900">
                            {cop(p.min_price)}
                          </p>
                        )}
                      </div>

                      <Link
                        href={`/catalogo/${p.slug}`}
                        className="inline-block w-full bg-blue-600 hover:bg-blue-700 text-white text-xs font-medium py-2 rounded transition"
                      >
                        Ver producto
                      </Link>
                    </div>
                  </th>
                ))}
              </tr>
            </thead>

            <tbody className="divide-y text-xs">
              {/* Row: Disponibilidad */}
              <tr className="hover:bg-gray-50/50">
                <th scope="row" className="p-3.5 font-semibold text-gray-700 bg-gray-50/60">
                  Disponibilidad
                </th>
                {data.products.map((p) => (
                  <td key={p.id} className="p-3.5 border-l">
                    {p.is_available ? (
                      <span className="text-emerald-700 font-semibold">
                        ✓ En stock ({p.total_stock} disponibles)
                      </span>
                    ) : (
                      <span className="text-red-600 font-semibold">✕ Agotado</span>
                    )}
                  </td>
                ))}
              </tr>

              {/* Row: Marca */}
              <tr className="hover:bg-gray-50/50">
                <th scope="row" className="p-3.5 font-semibold text-gray-700 bg-gray-50/60">
                  Marca
                </th>
                {data.products.map((p) => (
                  <td key={p.id} className="p-3.5 border-l font-medium">
                    {p.brand.name}
                  </td>
                ))}
              </tr>

              {/* Row: Garantía */}
              <tr className="hover:bg-gray-50/50">
                <th scope="row" className="p-3.5 font-semibold text-gray-700 bg-gray-50/60">
                  Garantía
                </th>
                {data.products.map((p) => (
                  <td key={p.id} className="p-3.5 border-l text-gray-700">
                    {p.warranty || "Garantía estándar del fabricante"}
                  </td>
                ))}
              </tr>

              {/* Section Header: Especificaciones Técnicas */}
              {data.attributes.length > 0 && (
                <tr className="bg-gray-100 font-bold text-gray-800">
                  <td colSpan={data.products.length + 1} className="p-3 uppercase text-[11px] tracking-wider">
                    Especificaciones Técnicas — {data.category.name}
                  </td>
                </tr>
              )}

              {/* Dynamic Attribute Rows */}
              {data.attributes.map((attr) => (
                <tr key={attr.code} className="hover:bg-gray-50/50">
                  <th scope="row" className="p-3.5 font-semibold text-gray-700 bg-gray-50/60">
                    {attr.name}
                  </th>
                  {data.products.map((p) => {
                    const val = p.attributes[attr.code]?.value || "N/A";
                    return (
                      <td key={p.id} className="p-3.5 border-l text-gray-800">
                        {val}
                      </td>
                    );
                  })}
                </tr>
              ))}

              {/* Row: Descripción */}
              <tr className="hover:bg-gray-50/50">
                <th scope="row" className="p-3.5 font-semibold text-gray-700 bg-gray-50/60">
                  Descripción
                </th>
                {data.products.map((p) => (
                  <td key={p.id} className="p-3.5 border-l text-gray-600 line-clamp-3">
                    {p.description}
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { useMemo, useState } from "react";
import {
  ArrowLeft,
  CheckCircle2,
  Package,
  RefreshCw,
  ShieldCheck,
  ShoppingCart,
} from "lucide-react";
import { addToCart } from "@/features/orders/cart-storage";
import { cop } from "@/features/orders/types";
import { useResource } from "./shared";
import type { PublicProductDetail, PublicVariant } from "./types";
import { CompareButton, ComparisonFloatingBar } from "./product-comparator";

export function ProductDetail({ slug }: { slug: string }) {
  const [revision, setRevision] = useState(0);
  const {
    data: product,
    error,
    loading,
  } = useResource<PublicProductDetail>(
    `/products/${encodeURIComponent(slug)}/`,
    revision,
  );

  const [selectedVariantId, setSelectedVariantId] = useState<number | null>(
    null,
  );
  const [activeImageIndex, setActiveImageIndex] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [addedNotice, setAddedNotice] = useState(false);

  const [selectionKey, setSelectionKey] = useState(`${slug}:${revision}`);
  if (selectionKey !== `${slug}:${revision}`) {
    setSelectionKey(`${slug}:${revision}`);
    setSelectedVariantId(null);
    setActiveImageIndex(0);
    setQuantity(1);
    setAddedNotice(false);
  }

  const selectedVariant: PublicVariant | null = useMemo(() => {
    if (!product?.variants) return null;
    return (
      product.variants.find((v) => v.id === selectedVariantId) ??
      product.variants.find((v) => v.stock > 0) ??
      product.variants[0] ??
      null
    );
  }, [product, selectedVariantId]);

  function handleVariantChange(variantId: number) {
    setSelectedVariantId(variantId);
    setQuantity(1);
    setAddedNotice(false);
  }

  function handleAddToCart() {
    if (!product || !selectedVariant || selectedVariant.stock <= 0) return;

    const label = `${product.name} · ${selectedVariant.name}`;
    addToCart(
      selectedVariant.id,
      quantity,
      label,
      undefined,
      selectedVariant.promotional_price ?? selectedVariant.price,
    );
    setAddedNotice(true);
  }

  if (loading) {
    return (
      <div className="detail-shell">
        <p role="status" style={{ textAlign: "center", padding: "60px 0" }}>
          Cargando detalles del producto...
        </p>
      </div>
    );
  }

  if (error || !product) {
    return (
      <div className="detail-shell">
        <nav className="detail-breadcrumb">
          <Link href="/catalogo">
            <ArrowLeft size={16} /> Volver al catálogo
          </Link>
        </nav>
        <div
          role="alert"
          className="error-message"
          style={{ margin: "24px 0" }}
        >
          <p>{error || "Producto no encontrado o no disponible."}</p>
          <button
            type="button"
            className="button secondary"
            onClick={() => setRevision((r) => r + 1)}
            style={{ marginTop: 12 }}
          >
            <RefreshCw size={16} /> Reintentar
          </button>
        </div>
      </div>
    );
  }

  const images = product.images || [];
  const currentImage = images[activeImageIndex] ?? images[0];
  const maxAvailableQuantity = selectedVariant
    ? Math.min(selectedVariant.stock, 10)
    : 1;

  return (
    <div className="detail-shell">
      {/* Breadcrumb Navigation */}
      <nav className="detail-breadcrumb" aria-label="Navegación secundaria">
        <Link href="/catalogo">
          <ArrowLeft
            size={14}
            style={{ display: "inline", verticalAlign: "middle" }}
          />{" "}
          Catálogo
        </Link>
        <span>/</span>
        <Link href={`/catalogo?category=${product.category.slug}`}>
          {product.category.name}
        </Link>
        <span>/</span>
        <span aria-current="page">{product.name}</span>
      </nav>

      <div className="detail-layout">
        {/* Left Column: Image Gallery */}
        <section className="gallery-container" aria-label="Galería de imágenes">
          <div className="main-image-box">
            {selectedVariant?.promotional_price && (
              <span className="promo-badge">
                {selectedVariant.promotion_name || "Oferta"}
              </span>
            )}
            {currentImage ? (
              <Image
                unoptimized
                src={currentImage.url}
                alt={currentImage.alt_text || product.name}
                width={450}
                height={380}
              />
            ) : (
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  color: "#94a3b8",
                  gap: 8,
                }}
              >
                <Package size={64} aria-hidden="true" />
                <span>Sin imagen disponible</span>
              </div>
            )}
          </div>

          {images.length > 1 && (
            <div className="gallery-thumbs" aria-label="Miniaturas de producto">
              {images.map((img, idx) => (
                <button
                  key={img.id}
                  type="button"
                  className={`thumb-btn ${idx === activeImageIndex ? "active" : ""}`}
                  onClick={() => setActiveImageIndex(idx)}
                  title={`Ver imagen ${idx + 1}`}
                >
                  <Image
                    unoptimized
                    src={img.url}
                    alt={img.alt_text || `${product.name} ${idx + 1}`}
                    width={60}
                    height={60}
                  />
                </button>
              ))}
            </div>
          )}
        </section>

        {/* Right Column: Product Info & Actions */}
        <section className="detail-info" aria-label="Información del producto">
          <div className="detail-category-brand">
            <span>{product.category.name}</span> ·{" "}
            <span>{product.brand.name}</span>
          </div>

          <h1 className="detail-title">{product.name}</h1>

          {/* Pricing Box */}
          <div className="detail-pricing-box">
            {selectedVariant?.promotional_price ? (
              <>
                <div className="detail-price-row">
                  <span
                    className="price-current has-discount"
                    style={{ fontSize: 26 }}
                  >
                    {cop(selectedVariant.promotional_price)}
                  </span>
                  <span className="price-original" style={{ fontSize: 18 }}>
                    {cop(selectedVariant.price)}
                  </span>
                  <span className="detail-promo-badge">
                    {selectedVariant.promotion_name || "Descuento"}
                  </span>
                </div>
                <small style={{ color: "#64748b" }}>
                  Precio promocional aplicado por tiempo limitado.
                </small>
              </>
            ) : (
              <div className="detail-price-row">
                <span className="price-current" style={{ fontSize: 26 }}>
                  {selectedVariant ? cop(selectedVariant.price) : "—"}
                </span>
              </div>
            )}
          </div>

          {/* Variants Selector */}
          {product.variants.length > 0 && (
            <div className="variant-selector-box">
              <label>Selecciona una variante / modelo:</label>
              <div className="variant-options" role="radiogroup">
                {product.variants.map((v) => {
                  const isSelected = v.id === selectedVariant?.id;
                  const isOutOfStock = v.stock <= 0;
                  return (
                    <button
                      key={v.id}
                      type="button"
                      role="radio"
                      aria-checked={isSelected}
                      className={`variant-chip ${isSelected ? "selected" : ""} ${isOutOfStock ? "out-of-stock" : ""}`}
                      onClick={() => handleVariantChange(v.id)}
                    >
                      {v.name}
                      {v.promotional_price ? " ★" : ""}
                      {isOutOfStock ? " (Agotado)" : ""}
                    </button>
                  );
                })}
              </div>

              {selectedVariant && (
                <div className="variant-details-meta">
                  <span>
                    <strong>SKU:</strong> {selectedVariant.sku}
                  </span>
                  {selectedVariant.attributes.map((attr) => (
                    <span key={attr.code}>
                      <strong>{attr.name}:</strong> {attr.value}
                    </span>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Stock Availability */}
          <div className="card-stock">
            {selectedVariant && selectedVariant.stock > 0 ? (
              <p className="stock-in" style={{ fontSize: 14, margin: 0 }}>
                ✓ {selectedVariant.stock} unidades disponibles para entrega
                inmediata
              </p>
            ) : (
              <p className="stock-out" style={{ fontSize: 14, margin: 0 }}>
                ✕ Variante actualmente agotada
              </p>
            )}
          </div>

          {/* Add to Cart Controls */}
          <div className="cart-action-box">
            {selectedVariant && selectedVariant.stock > 0 && (
              <div className="quantity-control">
                <label htmlFor="quantity-input">Cantidad:</label>
                <input
                  id="quantity-input"
                  type="number"
                  min={1}
                  max={maxAvailableQuantity}
                  value={quantity}
                  onChange={(e) => {
                    const val = parseInt(e.target.value, 10);
                    if (Number.isSafeInteger(val) && val >= 1) {
                      setQuantity(Math.min(val, maxAvailableQuantity));
                    }
                  }}
                />
                <span style={{ fontSize: 12, color: "#64748b" }}>
                  (Máx. {maxAvailableQuantity})
                </span>
              </div>
            )}

            <div className="flex items-center gap-3">
              <button
                type="button"
                className="button primary add-cart-btn flex-1"
                disabled={!selectedVariant || selectedVariant.stock <= 0}
                onClick={handleAddToCart}
              >
              <ShoppingCart
                size={18}
                style={{
                  display: "inline",
                  verticalAlign: "middle",
                  marginRight: 8,
                }}
              />
              {selectedVariant && selectedVariant.stock > 0
                ? "Añadir al carrito"
                : "Producto agotado"}
            </button>
              <CompareButton
                item={{
                  id: product.id,
                  name: product.name,
                  slug: product.slug,
                  category_id: product.category.id,
                  category_name: product.category.name,
                  image_url: images[0]?.url,
                }}
              />
            </div>

            <p className="cart-notice">
              * El carrito no reserva inventario hasta confirmar el pedido.
              Puedes comprar sin registrarte inicialmente.
            </p>

            {/* Added Notice Feedback */}
            {addedNotice && (
              <div className="cart-feedback-success" role="status">
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <CheckCircle2 size={18} />
                  <strong>¡Añadido al carrito con éxito!</strong>
                </div>
                <div className="cart-feedback-actions">
                  <Link href="/comprar">Ver carrito y finalizar compra →</Link>
                  <Link href="/catalogo">Seguir explorando</Link>
                </div>
              </div>
            )}
          </div>

          {/* Warranty Info */}
          {product.warranty && (
            <div className="warranty-badge">
              <ShieldCheck size={20} />
              <span>
                <strong>Garantía TTI:</strong> {product.warranty}
              </span>
            </div>
          )}

          {/* Description */}
          {product.description && (
            <div className="product-description-box">
              <h3>Descripción del producto</h3>
              <p
                style={{
                  whiteSpace: "pre-line",
                  color: "#334155",
                  lineHeight: 1.6,
                }}
              >
                {product.description}
              </p>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
